Section TOP.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (m : fmem) (DST dcap W wks maxLog lo : Z) (src : list Z).
  Notation SP := (bv_unsigned sp).
  Notation FB := (bv_unsigned sp - 160).
  Notation POST := (fse_decomp_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc DST dcap W wks maxLog src lo m).
  Notation WALL := [(bv_unsigned sp - FSE_DECOMP_STACK, bv_unsigned sp); (DST, DST + dcap); (W, W + wks)].
  Hypothesis SPR : 160 <= SP <= 2^47.
  Hypothesis HDC : 0 <= dcap <= 255.

  (* [comment removed for export] *)
  Lemma fdw_epi : forall m' R a4v (y1 y5 y6 y7 y8 y9 y10 y11 y12 y13 y15 y16 y17 y18 y19 y20 y21 y22 y23 y28 y29 y30 y31 : word),
    rw_cells psegs m' (FB + 88) [C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    stk psegs m' lo (FB + 88) -> lo <= FB ->
    munch WALL m m' -> wmono psegs m m' -> mem_inv psegs m' ->
    fse_decompress_wksp (repeat 0 256) dcap src maxLog wks = R ->
    dres DST dcap R m' a4v ->
    evt psegs POST (MS (mkR y1 (Z_to_bv 64 FB) gp tp y5 y6 y7 y8 y9 y10 y11 y12 y13 (Z_to_bv 64 a4v) y15 y16 y17 y18 y19 y20
                            y21 y22 y23 s8 s9 s10 s11 y28 y29 y30 y31)
                       F (Z_to_bv 64 0x1be74) fc None m' (seg_rom psegs)).
